def generate_hungarian_bank_deeplink(amount, reference, bank='otp'):
    base_url = ''
    params = {}

    if bank == 'otp':
        base_url = 'otpbankhu://'
        params = {
            'target': 'payment',
            'account': RECIPIENT_ACCOUNT,
            'amount': str(amount),
            'name': RECIPIENT_NAME,
            'message': reference
        }
    elif bank == 'k&h':
        base_url = 'khbankhu://'
        params = {
            'action': 'transfer',
            'beneficiary_account': RECIPIENT_ACCOUNT,
            'amount': str(amount),
            'beneficiary_name': RECIPIENT_NAME,
            'description': reference
        }
    elif bank == 'erste':
        base_url = 'erstehu://'
        params = {
            'type': 'transfer',
            'to_account': RECIPIENT_ACCOUNT,
            'sum': str(amount),
            'to_name': RECIPIENT_NAME,
            'note': reference
        }
    elif bank == 'raiffeisen':
        base_url = 'raiffeisenhu://'
        params = {
            'transfer': 'new',
            'account_number': RECIPIENT_ACCOUNT,
            'amount': str(amount),
            'payee_name': RECIPIENT_NAME,
            'comment': reference
        }
    elif bank == 'unicredit':
        base_url = 'unicredithu://'
        params = {
            'action': 'pay',
            'account': RECIPIENT_ACCOUNT,
            'value': str(amount),
            'recipient': RECIPIENT_NAME,
            'reference': reference
        }
    elif bank == 'cib':
        base_url = 'cibhu://'
        params = {
            'transfer': 'instant',
            'to': RECIPIENT_ACCOUNT,
            'amount': str(amount),
            'name': RECIPIENT_NAME,
            'message': reference
        }
    else:
        base_url = 'intent://payment'
        params = {
            'account': RECIPIENT_ACCOUNT,
            'amount': str(amount),
            'name': RECIPIENT_NAME,
            'message': reference
        }
        query_string = urlencode(params)
        return f'{base_url}?{query_string}Intent;scheme=bankapp;action=android.intent.action.VIEW;end;'

    query_string = urlencode(params)
    return f'{base_url}?{query_string}'

