def format_amount_for_payto(value):
    s = '{0:.2f}'.format(value).rstrip('0').rstrip('.')
    return s

def generate_payto_deeplink(amount_str, reference):
    params = {
        'amount': 'HUF:' + amount_str,
        'message': reference,
        'receiver-name': RECIPIENT_NAME
    }
    query = urlencode(params, quote_via=quote, safe='')
    return 'payto://iban/' + RECIPIENT_IBAN + '?' + query

@app.route('/', defaults={'path': ''})
@app.route('/<path:path>')
def catch_all(path):
    if path and os.path.exists(os.path.join(app.static_folder, path)):
        return send_from_directory(app.static_folder, path)
    return send_from_directory(app.static_folder, 'index.html')

@app.route('/api/payment/initiate', methods=['POST'])
def initiate_payment():
    try:
        if not request.is_json:
            return jsonify({'success': False, 'error': 'Content-Type must be application/json'}), 400
        data = request.get_json(silent=False)
