        amount_formatted = format_amount_for_payto(amount_value)
        transaction_id = 'ZSEBIBABA-' + datetime.utcnow().strftime('%Y%m%d%H%M%S') + '-' + str(uuid.uuid4())[:8].upper()
        deeplink = generate_payto_deeplink(amount_formatted, reference)
