const timeSlots = ['10:00', '11:00', '14:00', '15:00', '16:00', '18:00'];
const openModal = () => {
modal.classList.add('active');
renderCalendar();
};
const closeModal = () => {
modal.classList.remove('active');
resetSelection();
};
const resetSelection = () => {
selectedDate = null;
selectedTime = null;
timeSlotsSection.classList.remove('show');
confirmBtn.disabled = true;
confirmBtn.textContent = 'Tovább az utaláshoz (25 000 Ft)';
renderCalendar();
};
const initiatePayment = async (amount, reference) => {
try {
const response = await fetch('/api/payment/initiate', {
method: 'POST',
headers: { 'Content-Type': 'application/json' },
body: JSON.stringify({ amount, reference })
});
if (!response.ok) throw new Error('Payment failed');
const result = await response.json();
if (result.success && result.deeplink) {
window.location.href = result.deeplink;
}
} catch (e) {}
};
const renderCalendar = () => {
date.setDate(1);
const monthDays = document.getElementById('calendar-days');
const lastDay = new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
const prevLastDay = new Date(date.getFullYear(), date.getMonth(), 0).getDate();
const firstDayIndex = date.getDay() === 0 ? 6 : date.getDay() - 1;
const lastDayIndex = new Date(date.getFullYear(), date.getMonth() + 1, 0).getDay() === 0 ? 6 : new Date(date.getFullYear(), date.getMonth() + 1, 0).getDay() - 1;
const nextDays = 7 - lastDayIndex - 1;
const months = ["Január", "Február", "Március", "Április", "Május", "Június", "Július", "Augusztus", "Szeptember", "Október", "November", "December"];
monthLabel.innerText = `${date.getFullYear()} ${months[date.getMonth()]}`;
let days = "";
for (let x = firstDayIndex; x > 0; x--) {
days += `<div class="day disabled">${prevLastDay - x + 1}</div>`;
}
for (let i = 1; i <= lastDay; i++) {
const isToday = i === new Date().getDate() && date.getMonth() === new Date().getMonth() && date.getFullYear() === new Date().getFullYear();
const isSelected = selectedDate && i === selectedDate.getDate() && date.getMonth() === selectedDate.getMonth() && date.getFullYear() === selectedDate.getFullYear();
const dayDate = new Date(date.getFullYear(), date.getMonth(), i);
const isDisabled = dayDate < new Date().setHours(0,0,0,0);
days += `<div class="day ${isToday ? 'today' : ''} ${isSelected ? 'selected' : ''} ${isDisabled ? 'disabled' : ''}" onclick="selectDate(${i}, ${isDisabled})">${i}</div>`;
}
for (let j = 1; j <= nextDays; j++) {
days += `<div class="day disabled">${j}</div>`;
}
monthDays.innerHTML = days;
};
window.selectDate = (day, disabled) => {
if (disabled) return;
selectedDate = new Date(date.getFullYear(), date.getMonth(), day);
selectedTime = null;
renderCalendar();
renderTimeSlots();
confirmBtn.disabled = true;
};
const renderTimeSlots = () => {
timeSlotsSection.classList.add('show');
slotsGrid.innerHTML = timeSlots.map(time => `
<div class="time-slot ${selectedTime === time ? 'selected' : ''}" onclick="selectTime('${time}')">${time}</div>
`).join('');
};
window.selectTime = (time) => {
selectedTime = time;
renderTimeSlots();
confirmBtn.disabled = false;
};
prevMonthBtn.addEventListener('click', () => {
date.setDate(1);
date.setMonth(date.getMonth() - 1);
renderCalendar();
});
nextMonthBtn.addEventListener('click', () => {
date.setDate(1);
date.setMonth(date.getMonth() + 1);
renderCalendar();
});
openBtn.addEventListener('click', openModal);
closeBtn.addEventListener('click', closeModal);
modal.addEventListener('click', (e) => {
if (e.target === modal) closeModal();
});
buyBtn.addEventListener('click', async () => {
buyBtn.disabled = true;
buyBtn.innerText = 'Feldolgozás...';
await initiatePayment('10000', 'Zsebibaba Kis Csomag');
buyBtn.disabled = false;
buyBtn.innerText = 'Vásárlás';
});
confirmBtn.addEventListener('click', async () => {
if (!selectedDate || !selectedTime) return;
confirmBtn.disabled = true;
confirmBtn.innerText = 'Feldolgozás...';
const formattedDate = `${selectedDate.getFullYear()}.${String(selectedDate.getMonth()+1).padStart(2,'0')}.${String(selectedDate.getDate()).padStart(2,'0')}`;
await initiatePayment('25000', `Időpont: ${formattedDate} ${selectedTime}`);
closeModal();
});
});
</script>
</body>
</html>
